      const a = r.querySelector('a');
      const h3 = r.querySelector('h3');
      const snippet = r.querySelector('div[data-sncf], div.VwiC3b');
      return {
        title: h3?.innerText || '',
        url: a?.href || '',
        snippet: snippet?.innerText || ''
      };
